namespace RonSijm.FluidHumidifier.Factories.Deadline;

public class InnerQueueSchedulingConfigurationFactory(Action<Humidifier.Deadline.QueueTypes.SchedulingConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.Deadline.QueueTypes.SchedulingConfiguration>
{

    internal InnerQueuePriorityBalancedSchedulingConfigurationFactory PriorityBalancedFactory { get; set; }

    internal InnerQueueWeightedBalancedSchedulingConfigurationFactory WeightedBalancedFactory { get; set; }

    protected override Humidifier.Deadline.QueueTypes.SchedulingConfiguration Create()
    {
        var schedulingConfigurationResult = CreateSchedulingConfiguration();
        factoryAction?.Invoke(schedulingConfigurationResult);

        return schedulingConfigurationResult;
    }

    private Humidifier.Deadline.QueueTypes.SchedulingConfiguration CreateSchedulingConfiguration()
    {
        var schedulingConfigurationResult = new Humidifier.Deadline.QueueTypes.SchedulingConfiguration();

        return schedulingConfigurationResult;
    }
    public override void CreateChildren(Humidifier.Deadline.QueueTypes.SchedulingConfiguration result)
    {
        base.CreateChildren(result);

        result.PriorityBalanced ??= PriorityBalancedFactory?.Build();
        result.WeightedBalanced ??= WeightedBalancedFactory?.Build();
    }

} // End Of Class

